import{_ as e,o as a,c as r,ag as o}from"./chunks/framework.D-axA72T.js";const m=JSON.parse('{"title":"AI Inference","description":"","frontmatter":{"prev":{"text":"Observability","link":"/components/observability"},"next":{"text":"Hardware","link":"/hardware/"}},"headers":[],"relativePath":"components/ai-inference.md","filePath":"components/ai-inference.md","lastUpdated":1786792432000}'),n={name:"components/ai-inference.md"};function d(i,t,s,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="ai-inference" tabindex="-1">AI Inference <a class="header-anchor" href="#ai-inference" aria-label="Permalink to &quot;AI Inference&quot;">​</a></h1><p>Local LLM inference using a multi-pod architecture with dedicated GPU nodes for both AMD ROCm and NVIDIA CUDA workloads.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>The AI server uses a multi-pod design where each component runs as a separate deployment. GPU weights are bind-mounted from <code>/data/ai-models</code> on the inference nodes (<code>hostPath</code>), not from Longhorn.</p><table tabindex="0"><thead><tr><th>Pod</th><th>Node</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>ROCm</strong></td><td>aimax</td><td>llama.cpp with AMD ROCm GPU</td></tr><tr><td><strong>Thor</strong></td><td>thor</td><td>vLLM, ComfyUI, Speaches TTS/STT</td></tr><tr><td><strong>LiteLLM + Open WebUI</strong></td><td>aimax</td><td>OpenAI-compatible gateway and chat UI</td></tr></tbody></table><h2 id="rocm-pod" tabindex="-1">ROCm Pod <a class="header-anchor" href="#rocm-pod" aria-label="Permalink to &quot;ROCm Pod&quot;">​</a></h2><p>Runs <a href="https://github.com/ggerganov/llama.cpp" target="_blank" rel="noreferrer">llama.cpp</a> with ROCm GPU acceleration on the Minisforum MS-S1 Max (Ryzen AI Max+ 395). This node handles the bulk of LLM inference with 128GB of unified memory.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td><strong>Node</strong></td><td>aimax</td></tr><tr><td><strong>Taint</strong></td><td><code>rocm-inference=true:NoSchedule</code></td></tr><tr><td><strong>GPU</strong></td><td>AMD Radeon integrated (ROCm)</td></tr><tr><td><strong>Models</strong></td><td>Served from <code>/data/ai-models</code> hostPath</td></tr></tbody></table><h2 id="thor-pod" tabindex="-1">Thor Pod <a class="header-anchor" href="#thor-pod" aria-label="Permalink to &quot;Thor Pod&quot;">​</a></h2><p>Runs on the NVIDIA AGX Thor Jetson node with CUDA acceleration:</p><ul><li><strong><a href="https://docs.vllm.ai/" target="_blank" rel="noreferrer">vLLM</a></strong> - High-throughput LLM serving</li><li><strong><a href="https://github.com/comfyanonymous/ComfyUI" target="_blank" rel="noreferrer">ComfyUI</a></strong> - Image generation workflows</li><li><strong>Speaches</strong> - Text-to-speech and transcription via a custom <code>whisper-kokoro-thor-openai</code> image</li></ul><table tabindex="0"><thead><tr><th>Setting</th><th>Value</th></tr></thead><tbody><tr><td><strong>Node</strong></td><td>thor</td></tr><tr><td><strong>Taint</strong></td><td><code>cuda-inference=true:NoSchedule</code></td></tr><tr><td><strong>GPU</strong></td><td>NVIDIA Blackwell (CUDA)</td></tr><tr><td><strong>Memory</strong></td><td>128GB</td></tr></tbody></table><h2 id="litellm" tabindex="-1">LiteLLM <a class="header-anchor" href="#litellm" aria-label="Permalink to &quot;LiteLLM&quot;">​</a></h2><p><a href="https://litellm.ai/" target="_blank" rel="noreferrer">LiteLLM</a> acts as a unified API gateway, exposing all models from both ROCm and CUDA backends through a single <strong>OpenAI-compatible API</strong> endpoint. The APIs pod is pinned to the ROCm node and reaches GPU backends over in-cluster ClusterIP — not localhost.</p><h2 id="open-webui" tabindex="-1">Open WebUI <a class="header-anchor" href="#open-webui" aria-label="Permalink to &quot;Open WebUI&quot;">​</a></h2><p><a href="https://openwebui.com/" target="_blank" rel="noreferrer">Open WebUI</a> provides a ChatGPT-style web interface for interacting with local models. It runs as a sidecar in the same APIs pod as LiteLLM and talks to the gateway on <code>localhost:4000</code>.</p>',16)])])}const g=e(n,[["render",d]]);export{m as __pageData,g as default};
